('L8GUqRcJYAc',	'The Man Who Sold The World  Nirvana',	'#KaraokeCovers #KaraokeHits #KaraokeVersions

"The Man Who Sold The World" is a song that Nirvana covered in their 1993 MTV Unplugged concert. The song was originally sang by David Bowie from his 1970 album of the same name. Singer Midge Ure had also covered the song in 1982, 11 years before Nirvana. Kurt had listed "The Man Who Sold The World" to be 45th of the most favorite album on the list of his top 50 favorite albums. The song was later released as a promotional single from Nirvana''s Unplugged album in the year 1995.

Source: https://nirvana.fandom.com/wiki/The_Man_Who_Sold_The_World
 
