('AR_Jy3ZYBb8',	'With or Without You  U2',	'#KaraokeCovers #KaraokeHits #KaraokeVersions

"With or Without You" is a song by Irish rock band U2. It is the third track on their fifth studio album, The Joshua Tree (1987), and was released as the album''s lead single on 16 March 1987. The song was the group''s most successful single at the time, becoming their first number-one hit in both the United States and Canada by topping the Billboard Hot 100 for three weeks and the RPM national singles chart for one week, with a further three weeks at number two.

"With or Without You" features sustained guitar parts played by guitarist the Edge with a prototype of the Infinite Guitar, along with vocals by lead singer Bono and a bassline by bassist Adam Clayton. The song originated from a demo recorded in late 1985 that the group continued to work on throughout The Joshua Tree sessions. Ostensibly a troubled love song, the track''s lyrics were inspired by Bono''s conflicting feelings about the lives he led as a musician and domestic man.

Critics praised the song upon its release. It is frequently performed on the band''s tours, and it has appeared on many of their compilation albums and concert films. "With or Without You" is U2''s second most frequently covered song. In 2010, Rolling Stone magazine placed the song at number 132 on their list of "The 500 Greatest Songs of All Time".

With or Without You is a live CD/DVD U2 tribute album recorded by the Dutch band Kane. The DVD was filmed on September 20, 2000 at Plan C in Rotterdam. The CD was recorded a day later at Paridiso, Amsterdam. The album was released in December 2000, but only in the Netherlands.

Singles 
"Another Day""11 O''Clock Tick Tock""A Day Without Me""I Will Follow""Fire""Gloria""A Celebration""I Will Follow""New Year''s Day""Two Hearts Beat as One""Sunday Bloody Sunday""Pride (In the Name of Love)""The Unforgettable Fire""With or Without You""I Still Haven''t Found What I''m Looking For""Where the Streets Have No Name""In God''s Country""One Tree Hill""Desire""Angel of Harlem""When Love Comes to Town""All I Want Is You""The Fly""Mysterious Ways""One""Even Better Than the Real Thing""Who''s Gonna Ride Your Wild Horses""Numb""Lemon""Stay (Faraway, So Close!)""Hold Me, Thrill Me, Kiss Me, Kill Me""Miss Sarajevo" (ft. Luciano Pavarotti)"Discothèque""Staring at the Sun""Last Night on Earth""Please""If God Will Send His Angels""Mofo""Sweetest Thing""Beautiful Day""Stuck in a Moment You Can''t Get Out Of""Elevation""Walk On""Electrical Storm""Take Me to the Clouds Above""Vertigo""All Because of You""Sometimes You Can''t Make It on Your Own""City of Blinding Lights""The Saints Are Coming" (ft. Green Day)"Window in the Skies""The Ballad of Ronnie Drew""Get On Your Boots""Magnificent""I''ll Go Crazy If I Don''t Go Crazy Tonight""Ordinary Love""Invisible""The Miracle (of Joey Ramone)""Every Breaking Wave""Song for Someone""You''re the Best Thing About Me""Get Out of Your Own Way""Love Is Bigger Than Anything in Its Way"

