('9ac67zN4Pnw',	'Radiohead - Creep [Instrumental]',	'Instrumental karaoke version of "Creep" song by "Radiohead"

"Creep" is a song by the English alternative rock band Radiohead, released as their debut single in 1992. It later appeared on their first album, Pablo Honey (1993).

The lyrics express intense feelings of inadequacy and rejection. Yorke sings about feeling like an outsider and not belonging, with the iconic line "I''m a creep, I''m a weirdo" epitomizing this sentiment.

The song remains one of Radiohead''s most famous tracks. It has been covered by numerous artists across different genres and has been featured in various films, TV shows, and commercials.

[Verse 1]
When you were here before
Couldn''t look you in the eye
You''re just like an angel
Your skin makes me cry
You float like a feather
In a beautiful world
I wish I was special
You''re so fuckin'' special

[Chorus]
But I''m a creep, I''m a weirdo
What the hell am I doing here?
I don''t belong here

[Verse 2]
I don''t care if it hurts
I wanna have control
I want a perfect body
I want a perfect soul
I want you to notice
When I''m not around
You''re so fuckin'' special
I wish I was special

[Chorus]
But I''m a creep, I''m a weirdo
What the hell am I doing here?
I don''t belong here
Oh-oh, oh-oh

[Bridge]
She''s running out the door
She''s running
She run, run, run, run
Run

[Outro]
Whatever makes you happy
Whatever you want
You''re so fuckin'' special
I wish I was special
But I''m a creep, I''m a weirdo
What the hell am I doing here?
I don''t belong here
I don''t belong here',	'https://i.ytimg.com/vi/9ac67zN4Pnw/default.jpg',	'Karaoke Version Songs',	'2024-05-30 14:32:15'),
