('gxwiz34YHkw',	'Sheryl Crow - If It Makes You Happy (Lyrics)',	'Pls. Like and Subscribe...
And Comment...Thanks.....

Disclaimer:

This lyric video is created for the enjoyment of fans of Sheryl Crow and her music. The content, including lyrics and accompanying visuals, is intended to enhance the listener''s experience and appreciation of the song "If It Makes You Happy."

Please be aware that the lyrics may contain themes of self-discovery, independence, and personal reflection. Viewer discretion is advised.

The use of any copyrighted material is solely for the purpose of promoting the artist''s work and does not imply any endorsement or association with the creators of this video.

We do not claim ownership of the song or any associated rights. All rights belong to the respective copyright holders.

Thank you for supporting Sheryl Crow''s music.

"If It Makes You Happy" is a song by American singer-songwriter Sheryl Crow, released as the lead single from her 1996 eponymous album in September 1996. The song peaked at number 10 on the US Billboard Hot 100, becoming Crow''s final top-10 solo hit in the United States, and at number nine on the UK Singles Chart. It also reached number one in Canada and won Best Female Rock Vocal Performance at the 1997 Grammy Awards. In 2003, Q Magazine ranked "If It Makes You Happy" at number 663 in their list of the "1001 Best Songs Ever".

Youtube Video: https://www.youtube.com/watch?v=dyihQtBes1I

Follow Sheryl Crow:
Instagram: https://www.instagram.com/sherylcrow
Twitter: https://twitter.com/sherylcrow
Facebook: https://www.facebook.com/sherylcrow
Website: https://sherylcrow.com

Lyrics:

I''ve been long
A long way from here
Put on a poncho, played for mosquitoes
And drank ''til I was thirsty again
We went searchin''
Through thrift store jungles
Found Geronimo''s rifle, Marilyn''s shampoo
And Benny Goodman''s corset and pen
Well, okay, I made this up
I promised you I''d never give up
If it makes you happy
It can''t be that bad
If it makes you happy
Then why the hell are you so sad?
We get down
A real low down
You listen to Coltrane, derail your own train
Well, who hasn''t been there before?
I come proud
Around the hard way
Bring you comics in bed, scrape the mold off the bread
And serve you French toast again
Well, okay, I still get stoned
I''m not the kind of girl you''d take home
If it makes you happy
It can''t be that bad
If it makes you happy
Then why the hell are you so sad?
If it makes you happy
It can''t be that bad
If it makes you happy
Then why the hell are you so sad?
We''ve been far
Far away from here
Put on a poncho, played for mosquitoes
And everywhere in between
Well, okay, we get along
So what if right now everything''s wrong?
If it makes you happy
It can''t be that bad
If it makes you happy
Then why the hell are you so sad?
If it makes you happy
It can''t be that bad
If it makes you happy
Then why the hell are you so sad?

